def fasta_md5(seq: str) -> str:
    return hashlib.md5(seq.upper().encode('ascii', 'ignore')).hexdigest()


def alias_for_name(name: str) -> Optional[str]:
    if name == 'chrM':
        return 'M,chrMT,MT'
    if name == 'M':
        return 'chrM,chrMT,MT'
    if name == 'MT':
        return 'chrM,M,chrMT'
    if name.startswith('chr') and len(name) > 3:
        return name[3:]
    if name and (name[0].isdigit() or name in ('X', 'Y')):
        return 'chr' + name
    return None


