        elif a in ('-H', '--no-header'): no_header = True; i += 1
        elif a in ('-A', '--alias', '--alternative-name'): add_alias = True; i += 1
        elif a in ('-l', '--alt') and i+1 < len(argv): i += 2
        else: files.append(a); i += 1
    lines: List[str] = []
    if not no_header:
        lines.append('@HD\tVN:1.0\tSO:unsorted')
    if not files:
        write_text_output('\n'.join(lines) + ('\n' if lines else ''), output); return 0
    path = files[0]
    try:
        recs, _ = parse_fasta(path)
    except FileNotFoundError:
        write_stderr(f"samtools dict: Cannot open {path}: No such file or directory\n"); return 1
    if uri is None:
