# Alignment filtering and view --------------------------------------------------

def parse_regions(regs: List[str]) -> List[Tuple[str, int, int]]:
    out = []
    for r in regs:
        name, start, end, err = parse_region_string(r, None)
        if err:
            out.append((r, 1, 2**31-1))
        else:
            out.append((name, start or 1, end or 2**31-1))
    return out


def rec_overlaps_regions(rec: SamRecord, regions: List[Tuple[str, int, int]]) -> bool:
    if not regions: return True
    if rec.rname == '*' or rec.pos <= 0: return False
    s = rec.pos; e = record_end(rec)
    for rn, a, b in regions:
        if rec.rname == rn and e >= a and s <= b:
            return True
    return False


def has_index(path: str) -> bool:
    return path == '-' or os.path.exists(path + '.bai') or os.path.exists(path + '.csi') or (path.endswith('.bam') and os.path.exists(path[:-4] + '.bai'))


def is_bamish_path(path: str) -> bool:
    return path == '-' or path.endswith('.bam') or path.endswith('.cram')


def filter_records(records: List[SamRecord], require: int = 0, exclude: int = 0, include_any: int = 0,
                   min_mq: int = 0, min_qlen: int = 0, regions: Optional[List[Tuple[str,int,int]]] = None,
                   qnames: Optional[set] = None, qname_neg: bool = False,
                   tag_filter: Optional[Tuple[str, Optional[str]]] = None) -> List[SamRecord]:
    out = []
    for rec in records:
        fl = rec.flag
        if require and (fl & require) != require: continue
        if exclude and (fl & exclude): continue
        if include_any and (fl & include_any) == 0: continue
        if rec.mapq < min_mq: continue
        if min_qlen and cigar_query_len(rec.cigar) < min_qlen: continue
        if regions and not rec_overlaps_regions(rec, regions): continue
        if qnames is not None:
            present = rec.qname in qnames
            if present == qname_neg: continue
        if tag_filter is not None:
            tag, val = tag_filter
            tv = rec.tag_value(tag)
            if tv is None: continue
            if val is not None and tv != val: continue
        out.append(rec)
    return out


def cmd_view(argv: List[str], full_argv: List[str]) -> int:
    if any(a in ('--help', '-?') for a in argv):
        write_stdout(VIEW_HELP); return 0
    output_bam = False; include_header = False; header_only = False; count_only = False
    no_pg = False; out_path = None; output_fmt = None; fai_path = None
    require = 0; exclude = 0; include_any = 0; min_mq = 0; min_qlen = 0
    qnames = None; qname_neg = False; tag_filter = None; save_counts = None
    positional: List[str] = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-b', '--bam', '-u', '--uncompressed', '-1', '--fast', '-C', '--cram'):
            output_bam = True; i += 1
        elif a in ('-h', '--with-header'):
            include_header = True; i += 1
        elif a in ('-H', '--header-only'):
            header_only = True; include_header = True; i += 1
        elif a == '--no-header':
            include_header = False; i += 1
        elif a in ('-c', '--count'):
            count_only = True; i += 1
        elif a in ('-o', '--output') and i+1 < len(argv):
            out_path = argv[i+1]; i += 2
        elif a in ('-O', '--output-fmt') and i+1 < len(argv):
            output_fmt = argv[i+1].split(',',1)[0].upper(); i += 2
        elif a in ('-t', '--fai-reference') and i+1 < len(argv):
            fai_path = argv[i+1]; i += 2
        elif a in ('-T', '--reference', '-@', '--threads', '--input-fmt-option', '--output-fmt-option', '--verbosity') and i+1 < len(argv):
            i += 2
        elif a in ('-S', '-M', '-P', '--use-index', '--fetch-pairs', '--write-index'):
            i += 1
        elif a == '--no-PG':
            no_pg = True; i += 1
        elif a in ('-f', '--require-flags') and i+1 < len(argv):
            require |= parse_flag_value(argv[i+1]) or 0; i += 2
        elif a in ('-F', '--exclude-flags', '--excl-flags') and i+1 < len(argv):
            exclude |= parse_flag_value(argv[i+1]) or 0; i += 2
        elif a in ('--rf', '--incl-flags', '--include-flags') and i+1 < len(argv):
            include_any |= parse_flag_value(argv[i+1]) or 0; i += 2
        elif a == '-G' and i+1 < len(argv):
            # Exclude reads with all bits present.  Approximate by adding to exclude.
            exclude |= parse_flag_value(argv[i+1]) or 0; i += 2
        elif a in ('-q', '--min-MQ') and i+1 < len(argv):
            min_mq = parse_int(argv[i+1]); i += 2
        elif a in ('-m', '--min-qlen') and i+1 < len(argv):
            min_qlen = parse_int(argv[i+1]); i += 2
        elif a in ('-N', '--qname-file') and i+1 < len(argv):
            fn = argv[i+1]; qname_neg = fn.startswith('^'); fn2 = fn[1:] if qname_neg else fn
            try:
                with open(fn2) as fh: qnames = set(x.strip().split()[0] for x in fh if x.strip())
            except FileNotFoundError: qnames = set()
            i += 2
