    while i < len(argv):
        a=argv[i]
        if a == '-n': by_name=True; i+=1
        elif a in ('-o','--output') and i+1 < len(argv): out=argv[i+1]; i+=2
        elif a in ('-O','--output-fmt') and i+1 < len(argv): fmt=argv[i+1].upper(); i+=2
        elif a == '--no-PG': no_pg=True; i+=1
