def main(argv: List[str]) -> int:
    if len(argv) == 1:
        write_stderr(TOP_HELP); return 1
    cmd = argv[1]
    if cmd == '--help': write_stdout(TOP_HELP); return 0
    if cmd == '--version' or cmd == 'version': write_stdout(VERSION_TEXT); return 0
    if cmd == '--version-only': write_stdout(f"{VERSION}+htslib-{HTSLIB}\n"); return 0
    if cmd == '-h' or cmd.startswith('-'):
        write_stderr(f"[main] unrecognized command '{cmd}'\n"); return 1
    if cmd == 'help':
        if len(argv) == 2:
            write_stdout(TOP_HELP); return 0
        # Observed behavior delegates to the subcommand with no args.
        return dispatch(argv[2], [], [argv[0], argv[2]])
    return dispatch(cmd, argv[2:], argv)


def dispatch(cmd: str, args: List[str], full_argv: List[str]) -> int:
    if cmd == 'flags': return cmd_flags(args)
    if cmd == 'faidx': return faidx_like(args, False)
    if cmd == 'fqidx': return faidx_like(args, True)
    if cmd == 'dict': return cmd_dict(args)
    if cmd == 'view': return cmd_view(args, full_argv)
    if cmd == 'head': return cmd_head(args)
    if cmd == 'flagstat': return cmd_flagstat(args)
    if cmd == 'idxstats': return cmd_idxstats(args)
    if cmd == 'depth': return cmd_depth(args)
    if cmd == 'coverage': return cmd_coverage(args)
    if cmd == 'mpileup': return cmd_mpileup(args)
    if cmd == 'index': return cmd_index(args)
    if cmd == 'quickcheck': return cmd_quickcheck(args)
    if cmd == 'sort': return cmd_sort(args, full_argv)
    if cmd == 'fasta': return cmd_fasta_fastq(args, False)
    if cmd == 'fastq': return cmd_fasta_fastq(args, True)
    if cmd in ('cat','merge','collate','split','fixmate','markdup','calmd','reheader','addreplacerg','ampliconclip','ampliconstats','stats','bedcov','checksum','consensus','import','reference','reset','cram-size','phase','depad','samples','tview','targetcut'):
        return unsupported_cmd(cmd, args)
    write_stderr(f"[main] unrecognized command '{cmd}'\n"); return 1


if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(1)
