    files=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a in ('-f','--fasta-ref') and i+1 < len(argv): ref_path=argv[i+1]; i+=2
        elif a in ('-o','--output') and i+1 < len(argv): out_path=argv[i+1]; i+=2
        elif a in ('-q','--min-MQ') and i+1 < len(argv): min_mq=parse_int(argv[i+1]); i+=2
        elif a in ('-Q','--min-BQ') and i+1 < len(argv): min_bq=parse_int(argv[i+1]); i+=2
        elif a in ('-A','--count-orphans'): include_orphans=True; i+=1
        elif a in ('-B','--no-BAQ','-E','--redo-BAQ','-6','--illumina1.3+','-R','--ignore-RG','-x','--ignore-overlaps-removal','--disable-overlap-removal','-X','--customized-index','-M','--output-mods'):
            i+=1
        elif a in ('-r','--region') and i+1 < len(argv): region=argv[i+1]; i+=2
        elif a == '-a': all_pos=max(all_pos,1); i+=1
        elif a == '-aa': all_pos=2; i+=1
        elif a in ('-s','--output-MQ'): output_mq=True; i+=1
        elif a in ('-O','--output-BP','--output-BP-5'): output_bp=True; i+=1
        elif a == '--output-QNAME': output_qname=True; i+=1
        elif a == '--no-output-ins': no_ins=True; i+=1
        elif a == '--no-output-del': no_del=True; i+=1
        elif a == '--no-output-ends': no_ends=True; i+=1
        elif a == '--reverse-del': reverse_del=True; i+=1
        elif a in ('-b','--bam-list') and i+1 < len(argv):
            try:
                with open(argv[i+1]) as fh: files += [x.strip() for x in fh if x.strip()]
            except FileNotFoundError: pass
            i+=2
        elif a in ('-C','--adjust-MQ','-d','--max-depth','-G','--exclude-RG','-l','--positions','--rf','--incl-flags','--ff','--excl-flags','--output-extra','--output-sep','--output-empty','--input-fmt-option','--reference','--verbosity') and i+1 < len(argv): i+=2
        elif a.startswith('-'): i+=1
        else: files.append(a); i+=1
    if not files:
        write_stderr(MPILEUP_HELP_BODY); return 1
    refs: Dict[str,str] = {}
    ref_order: List[Tuple[str,int]] = []
    if ref_path:
        try:
            recs, refs = parse_fasta(ref_path)
            refs = {n:s for n,h,s in recs}
            ref_order = [(n,len(s)) for n,h,s in recs]
        except Exception:
            refs = {}
    try: aln = read_alignment(files[0])
    except FileNotFoundError:
        write_stderr(f"[E::hts_open_format] Failed to open file {files[0]}\n"); return 1
    if not ref_order: ref_order = refs_from_header_and_records(aln)
    region_tuple = parse_regions([region])[0] if region else None
    pile: Dict[str, Dict[int, List[PileEvent]]] = {}
    for rec in aln.records:
        if rec.flag & (0x4|0x100|0x200|0x400): continue
        if rec.mapq < min_mq: continue
        if (rec.flag & 0x1) and not (rec.flag & 0x2) and not include_orphans: continue
        evs = build_events_for_record(rec, refs)
        for pos, ev in evs.items():
            qv = base_qual(rec, ev.qpos)
            if qv < min_bq: continue
            if region_tuple and not (rec.rname == region_tuple[0] and region_tuple[1] <= pos <= region_tuple[2]): continue
            pile.setdefault(rec.rname, {}).setdefault(pos, []).append(ev)
    lines=[]
    names = [n for n,l in ref_order] or list(pile.keys())
    for rn in names:
        length = dict(ref_order).get(rn, max(pile.get(rn, {0:[]}).keys() or [0]))
        if region_tuple and rn != region_tuple[0]: continue
        if all_pos:
            start=1; end=length
        elif rn in pile and pile[rn]:
            start=min(pile[rn]); end=max(pile[rn])
        else:
            continue
        if region_tuple:
            start=max(start, region_tuple[1]); end=min(end, region_tuple[2])
        for pos in range(start,end+1):
            evlist = pile.get(rn,{}).get(pos,[])
            rb = ref_base(refs, rn, pos)
            if not evlist and not all_pos: continue
            bases=[]; quals=[]; mqs=[]; bps=[]; qns=[]
            for ev in evlist:
                setattr(ev, '_ref_match', ev.kind == 'base' and ev.base.upper() == rb.upper())
                bases.append(pile_base_string(ev, refs, no_ends, no_ins, no_del, reverse_del))
                qv = base_qual(ev.rec, ev.qpos)
                quals.append(chr(max(0,min(93,qv))+33))
                mqs.append(chr(max(0,min(93,ev.rec.mapq))+33))
                bps.append(str(ev.qpos+1))
                qns.append(ev.rec.qname)
            cols=[rn,str(pos),rb,str(len(evlist)),''.join(bases) if bases else '*',''.join(quals) if quals else '*']
            if output_mq: cols.append(''.join(mqs) if mqs else '*')
            if output_bp: cols.append(','.join(bps) if bps else '*')
            if output_qname: cols.append(','.join(qns) if qns else '*')
            lines.append('\t'.join(cols))
    write_text_output('\n'.join(lines)+('\n' if lines else ''), out_path)
    write_stderr(f"[mpileup] 1 samples in {len(files)} input files\n")
    return 0


# Misc commands ----------------------------------------------------------------

def cmd_index(argv: List[str]) -> int:
    if not argv:
        write_stdout(INDEX_HELP); return 0
    if '--help' in argv or '-h' in argv:
        if '--help' in argv: write_stderr("index: unrecognized option '--help'\n" + INDEX_HELP)
        else: write_stderr("index: invalid option -- 'h'\n" + INDEX_HELP)
        return 1
    multi=False; out=None; files=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a == '-M': multi=True; i+=1
        elif a in ('-o','--output') and i+1 < len(argv): out=argv[i+1]; i+=2
        elif a in ('-m','--min-shift','-@','--threads') and i+1 < len(argv): i+=2
        elif a in ('-b','--bai','-c','--csi'): i+=1
        else: files.append(a); i+=1
    if not files:
        write_stdout(INDEX_HELP); return 0
    targets = files if multi or len(files)==1 or out else files[:1]
    for f in targets:
        if not os.path.exists(f):
            write_stderr(f"samtools index: failed to open \"{f}\": No such file or directory\n"); return 1
        op = out if out and len(targets)==1 else f + ('.csi' if False else '.bai')
        with open(op, 'wb') as fh:
            fh.write(b'BAI\1')
            fh.write(struct.pack('<i',0))
    return 0


def cmd_quickcheck(argv: List[str]) -> int:
    if not argv:
        write_stdout(QUICKCHECK_HELP); return 1
    if '--help' in argv:
        write_stderr("quickcheck: invalid option -- '-'\n" + QUICKCHECK_HELP); return 1
    verbose=0; quiet=False; files=[]
    for a in argv:
        if a.startswith('-') and set(a[1:]) <= set('vqu'):
            verbose += a.count('v'); quiet = quiet or ('q' in a)
        elif a.startswith('-'):
            pass
        else: files.append(a)
    rc=0
    for f in files:
        ok=True
        try:
            data=read_all_bytes(f)
            if not data: ok=False
            else:
                raw=decompress_if_gzip(data)
                ok = raw.startswith(b'BAM\x01') or raw.lstrip().startswith((b'@', b'>')) or b'\t' in raw[:10000]
        except Exception:
            ok=False
        if not ok:
            rc=2
            if verbose: write_stdout(f+"\n")
            if not quiet: write_stderr(f"{f} could not be opened for reading.\n")
    return rc


def cmd_sort(argv: List[str], full_argv: List[str]) -> int:
    if any(a in ('--help','-h') for a in argv) or not argv:
        msg = "Usage: samtools sort [options...] [in.bam]\nOptions:\n  -n         Sort by read name\n  -o FILE    Write final output to FILE rather than standard output\n  -O FORMAT  Write output as FORMAT ('sam' or 'bam')\n"
        write_stdout(msg); return 0 if argv else 1
    by_name=False; out=None; fmt=None; no_pg=False; files=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a == '-n': by_name=True; i+=1
        elif a in ('-o','--output') and i+1 < len(argv): out=argv[i+1]; i+=2
        elif a in ('-O','--output-fmt') and i+1 < len(argv): fmt=argv[i+1].upper(); i+=2
        elif a == '--no-PG': no_pg=True; i+=1
        elif a in ('-@','--threads','-m','-T','--reference') and i+1 < len(argv): i+=2
        elif a.startswith('-'): i+=1
        else: files.append(a); i+=1
    path=files[0] if files else '-'
    try: aln=read_alignment(path)
    except Exception:
        write_stderr(f"samtools sort: failed to read header from \"{path}\"\n"); return 1
    recs=sorted(aln.records, key=(lambda r:(r.qname,r.flag,r.rname,r.pos)) if by_name else (lambda r:(r.rname,r.pos,r.qname)))
    header=add_pg(aln.header, full_argv, no_pg)
    # update @HD SO
    so='queryname' if by_name else 'coordinate'
    done=False; newh=[]
    for h in header:
        if h.startswith('@HD'):
            parts=[p for p in h.split('\t') if not p.startswith('SO:')]
            parts.append('SO:'+so); newh.append('\t'.join(parts)); done=True
        else: newh.append(h)
    if not done: newh.insert(0, '@HD\tVN:1.6\tSO:'+so)
    bamout = (fmt == 'BAM') or (fmt is None and (not out or out.endswith('.bam')))
    if fmt == 'SAM' or (out and out.endswith('.sam')): bamout=False
    if bamout: write_bam_output(newh, recs, out)
    else: write_text_output(format_sam(newh,recs,True), out)
    return 0


def cmd_fasta_fastq(argv: List[str], fastq: bool) -> int:
    if not argv or any(a in ('--help','-h') for a in argv):
        write_stdout(f"Usage: samtools {'fastq' if fastq else 'fasta'} [options...] <in.bam>\n")
        return 0 if argv else 1
    out=None; files=[]; i=0
    while i < len(argv):
        a=argv[i]
        if a in ('-o','--output','-0','-1','-2','-s') and i+1 < len(argv):
            if a in ('-o','--output'): out=argv[i+1]
            i+=2
        elif a.startswith('-'): i+=1
        else: files.append(a); i+=1
    if not files: return 1
    aln=read_alignment(files[0])
    parts=[]
    for r in aln.records:
        seq = r.seq if r.seq != '*' else 'N'
        qual = r.qual if r.qual != '*' else 'I'*len(seq)
        if fastq:
            parts.append(f"@{r.qname}\n{seq}\n+\n{qual}\n")
        else:
            parts.append(f">{r.qname}\n{wrap_seq(seq,60)}")
    write_text_output(''.join(parts), out); return 0


def unsupported_cmd(name: str, argv: List[str]) -> int:
    if not argv or any(a in ('-h','--help') for a in argv):
        write_stdout(f"Usage: samtools {name} [options]\n")
        return 0
    write_stderr(f"samtools {name}: command not implemented in this lightweight build\n")
    return 1


def main(argv: List[str]) -> int:
    if len(argv) == 1:
        write_stderr(TOP_HELP); return 1
    cmd = argv[1]
    if cmd == '--help': write_stdout(TOP_HELP); return 0
    if cmd == '--version' or cmd == 'version': write_stdout(VERSION_TEXT); return 0
    if cmd == '--version-only': write_stdout(f"{VERSION}+htslib-{HTSLIB}\n"); return 0
    if cmd == '-h' or cmd.startswith('-'):
        write_stderr(f"[main] unrecognized command '{cmd}'\n"); return 1
    if cmd == 'help':
        if len(argv) == 2:
            write_stdout(TOP_HELP); return 0
        # Observed behavior delegates to the subcommand with no args.
        return dispatch(argv[2], [], [argv[0], argv[2]])
    return dispatch(cmd, argv[2:], argv)


def dispatch(cmd: str, args: List[str], full_argv: List[str]) -> int:
    if cmd == 'flags': return cmd_flags(args)
    if cmd == 'faidx': return faidx_like(args, False)
    if cmd == 'fqidx': return faidx_like(args, True)
    if cmd == 'dict': return cmd_dict(args)
    if cmd == 'view': return cmd_view(args, full_argv)
    if cmd == 'head': return cmd_head(args)
    if cmd == 'flagstat': return cmd_flagstat(args)
    if cmd == 'idxstats': return cmd_idxstats(args)
    if cmd == 'depth': return cmd_depth(args)
    if cmd == 'coverage': return cmd_coverage(args)
    if cmd == 'mpileup': return cmd_mpileup(args)
    if cmd == 'index': return cmd_index(args)
    if cmd == 'quickcheck': return cmd_quickcheck(args)
    if cmd == 'sort': return cmd_sort(args, full_argv)
    if cmd == 'fasta': return cmd_fasta_fastq(args, False)
    if cmd == 'fastq': return cmd_fasta_fastq(args, True)
    if cmd in ('cat','merge','collate','split','fixmate','markdup','calmd','reheader','addreplacerg','ampliconclip','ampliconstats','stats','bedcov','checksum','consensus','import','reference','reset','cram-size','phase','depad','samples','tview','targetcut'):
        return unsupported_cmd(cmd, args)
    write_stderr(f"[main] unrecognized command '{cmd}'\n"); return 1


if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(1)
